import AppKit
import SwiftUI

extension Theme {
    /// Semantic colors of the 1.0 black-and-white language (docs/DESIGN.md, "1.0"). Each is a
    /// color set in Assets.xcassets with a light and a dark variant; `ColorResource` symbols are
    /// generated by the asset catalog compiler. Views never use literal colors.
    enum Colors {
        // MARK: Grounds and surfaces

        /// The window ground: #FFFFFF / #000000.
        static let ground = Color(.ground)
        /// Sidebars, inline fields on the ground and quiet panels: #F5F5F7 / #1C1C1E.
        static let surface = Color(.surface)
        /// Secondary buttons, the segmented pill track, selected sidebar rows, the offline
        /// banner: #E8E8ED / #2C2C2E.
        static let surface2 = Color(.surface2)
        /// Cards, tables, sheets, inputs and the selected segment, a translucent glass fill so text
        /// stays crisp: white at 80% / #1C1C1E at 72%.
        static let card = Color(.card)

        // MARK: Text

        /// Primary text and the primary (ink) button fill: #000000 / #FFFFFF.
        static let ink = Color(.ink)
        /// Text on an ink fill (primary buttons, avatars): the ground color.
        static let onInk = Color(.ground)
        /// Secondary text, body copy under headings, masked values: #3F3F42 / #AEAEB2.
        static let mutedText = Color(.mutedText)
        /// Section labels, timestamps, counts, placeholders: #5C5C61 / #8E8E93.
        static let subtleText = Color(.subtleText)
        /// Separators inside mono labels (the `/` in `02 / 05`). Decorative only: it does not
        /// meet text contrast, so never use it for information the user must read.
        static let faintText = Color(.faintText)

        // MARK: Lines

        /// Default 1 pt borders and dividers: black at 8% / white at 10%.
        static let hairline = Color(.hairline)
        /// Outline buttons and chips, inputs, the window outline: black at 16% / white at 20%.
        static let hairlineStrong = Color(.hairlineStrong)

        // MARK: Accents and states

        /// The current or interactive state: pending dots, links, focus rings and the Modified /
        /// Will push chips. Ink since 1.0 (#000000 / #FFFFFF; the brand blue is gone). Also the
        /// app's global accent color.
        static let brand = Color(.brand)
        /// Needs attention: drift, missing values, offline: #8A6316 / #D9A441.
        static let warning = Color(.warning)
        /// Healthy, verified, strong: #1F7A55 / #3FB283.
        static let success = Color(.success)
        /// Destructive actions and failures: #CA2121 / #EC6A6A.
        static let danger = Color(.danger)

        // MARK: Component colors

        /// The count badge inside an ink pill (toolbar Sync).
        static let inkBadge = Color(.inkBadge)
        /// The dots of ``DotGridBackground``.
        static let dotGrid = Color(.dotGrid)
        /// The one soft shadow, under sheets drawn in the window (``Card`` with `.sheet`).
        static let shadow = Color(.shadow)
        /// The dimmed window behind the ⌘K jump palette (board Main2-Search).
        static let scrim = Color(.scrim)
        /// Under the main window's glass panels (board Main2-Home): black at 8% / 40%.
        static let panelShadow = Color(.panelShadow)
        /// The main window's soft ground (board Main2-Home): #F8F7F6 / #121214, lit from each
        /// corner by a glow (``MainWindowGround``).
        static let mainGround = Color(.mainGround)
        static let mainGlowTopLeading = Color(.mainGlowTopLeading)
        static let mainGlowTopTrailing = Color(.mainGlowTopTrailing)
        static let mainGlowBottomTrailing = Color(.mainGlowBottomTrailing)
        static let mainGlowBottomLeading = Color(.mainGlowBottomLeading)
        /// The notch island (``NotchIslandView``): black, white and dimmed white in both
        /// appearances, so it reads as part of the hardware notch.
        static let island = Color(.island)
        static let islandInk = Color(.islandInk)
        static let islandMuted = Color(.islandMuted)

        /// Secondary text and symbols in a native `List` row that can be selected: the
        /// hierarchical secondary style, so the text stays legible on the system selection
        /// highlight (where a fixed color such as `subtleText` would not).
        static let onSelectionSecondary = HierarchicalShapeStyle.secondary

        /// The window background for AppKit (``View/fxWindowBackground()``). Dynamic: it follows
        /// the window's appearance.
        static let windowBackground = NSColor(resource: .ground)

        /// The notes editor's AppKit text and tokens (1.0 N2). Dynamic, like ``windowBackground``.
        enum Editor {
            static let ink = NSColor(resource: .ink)
            static let mutedText = NSColor(resource: .mutedText)
            static let subtleText = NSColor(resource: .subtleText)
            static let surface2 = NSColor(resource: .surface2)
            static let hairlineStrong = NSColor(resource: .hairlineStrong)
            static let danger = NSColor(resource: .danger)
        }

        // MARK: Legacy names (v0.2 screens; the screen agents migrate them)

        /// Legacy name of ``brand``.
        static let accent = brand
        /// Legacy name of ``ground``.
        static let background = ground
        /// Legacy name of ``ink``.
        static let textPrimary = ink
        /// Legacy name of ``mutedText``.
        static let textSecondary = mutedText
        /// Local changes that are not yet on GitHub: the brand blue (pending dots, Will push).
        static let pending = brand
    }
}
